public class ProgramacionDinamicaEsquema {
    // Ilustración conceptual de la estructura Top-Down vs Bottom-Up en Java

    // Top-Down con Memoización (Cache genérica)
    public static int resolverTopDown(int estado, Integer[] memo) {
        if (esCasoBase(estado)) {
            return valorCasoBase(estado);
        }
        if (memo[estado] != null) {
            return memo[estado]; // Retorno en O(1) de subproblema superpuesto
        }
        int mejor = Integer.MAX_VALUE;
        for (int transicion : obtenerTransiciones(estado)) {
            int actual = costo(estado, transicion) + resolverTopDown(transicion, memo);
            if (actual < mejor) mejor = actual;
        }
        memo[estado] = mejor;
        return mejor;
    }

    private static boolean esCasoBase(int e) { return e <= 0; }
    private static int valorCasoBase(int e) { return 0; }
    private static int[] obtenerTransiciones(int e) { return new int[]{e - 1}; }
    private static int costo(int e, int t) { return 1; }
}

public static int fibonacci(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;

    // Implementación fiel sobre la interfaz VectorTDA de la cátedra UADE
    VectorTDA<Integer> aux = new Vector<Integer>();
    aux.inicializarVector(n + 1);
    aux.agregarElemento(0, 0);
    aux.agregarElemento(1, 1);

    for (int i = 2; i <= n; i++) {
        int f_prev1 = aux.recuperarElemento(i - 1);
        int f_prev2 = aux.recuperarElemento(i - 2);
        aux.agregarElemento(i, f_prev1 + f_prev2);
    }

    return aux.recuperarElemento(n);
}

// Versión con optimización espacial O(1) de memoria
public static int fibonacciOptimizado(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) {
        int c = a + b;
        a = b;
        b = c;
    }
    return b;
}

public static int cambio(VectorTDA<Integer> monedas, int v) throws Exception {
    int cantidadMonedas = monedas.capacidadVector();
    int INF = 9999999; // Representación de infinito compatible con aritmética

    // Dimensiones requeridas: n filas x (v + 1) columnas
    int dimensionMatriz = Math.max(cantidadMonedas, v + 1);
    MatrizTDA<Integer> m = new Matriz<Integer>();
    m.inicializarMatriz(dimensionMatriz);

    // Inicializar toda la matriz con infinito y columna 0 con 0
    for (int i = 0; i < cantidadMonedas; i++) {
        for (int j = 0; j <= v; j++) {
            m.setearValor(i, j, (j == 0) ? 0 : INF);
        }
    }

    // Primera fila: moneda de índice 0
    int d0 = monedas.recuperarElemento(0);
    for (int j = 1; j <= v; j++) {
        if (d0 <= j) {
            int previo = m.obtenerValor(0, j - d0);
            if (previo != INF) {
                m.setearValor(0, j, 1 + previo);
            }
        }
    }

    // Filas subsiguientes
    for (int i = 1; i < cantidadMonedas; i++) {
        int di = monedas.recuperarElemento(i);
        for (int j = 1; j <= v; j++) {
            int opcionSinMoneda = m.obtenerValor(i - 1, j);
            int opcionConMoneda = INF;

            if (di <= j) {
                int previo = m.obtenerValor(i, j - di);
                if (previo != INF) {
                    opcionConMoneda = 1 + previo;
                }
            }
            m.setearValor(i, j, Math.min(opcionSinMoneda, opcionConMoneda));
        }
    }

    return m.obtenerValor(cantidadMonedas - 1, v);
}

// Reconstrucción de la solución óptima
public static VectorTDA<Integer> reconstruirCambio(VectorTDA<Integer> monedas, MatrizTDA<Integer> m, int v) {
    int i = monedas.capacidadVector() - 1;
    int j = v;
    VectorTDA<Integer> seleccionadas = new Vector<Integer>();
    seleccionadas.inicializarVector(v + 1); // Capacidad holgada
    int pos = 0;

    while (j > 0 && i >= 0) {
        if (i > 0 && m.obtenerValor(i, j).equals(m.obtenerValor(i - 1, j))) {
            i--;
        } else {
            int di = monedas.recuperarElemento(i);
            seleccionadas.agregarElemento(pos++, di);
            j = j - di;
        }
    }
    return seleccionadas;
}

public static int mochila(VectorTDA<Integer> pesos, VectorTDA<Integer> valores, int p) throws Exception {
    int n = pesos.capacidadVector();

    // Corrección para soportar índices n y p con MatrizTDA de cátedra
    int dim = Math.max(n + 1, p + 1);
    MatrizTDA<Integer> m = new Matriz<Integer>();
    m.inicializarMatriz(dim);

    // Inicializar fila 0 y columna 0 en 0
    for (int i = 0; i <= n; i++) {
        m.setearValor(i, 0, 0);
    }
    for (int j = 0; j <= p; j++) {
        m.setearValor(0, j, 0);
    }

    // Llenado bottom-up
    for (int i = 1; i <= n; i++) {
        int pesoObj = pesos.recuperarElemento(i - 1);
        int valorObj = valores.recuperarElemento(i - 1);

        for (int j = 0; j <= p; j++) {
            int sinObjeto = m.obtenerValor(i - 1, j);
            if (pesoObj > j) {
                m.setearValor(i, j, sinObjeto);
            } else {
                int conObjeto = valorObj + m.obtenerValor(i - 1, j - pesoObj);
                m.setearValor(i, j, Math.max(sinObjeto, conObjeto));
            }
        }
    }

    return m.obtenerValor(n, p);
}

// Reconstrucción de objetos seleccionados
public static VectorTDA<Integer> reconstruirMochila(VectorTDA<Integer> pesos, MatrizTDA<Integer> m, int p) {
    int n = pesos.capacidadVector();
    int i = n;
    int j = p;
    VectorTDA<Integer> elegidos = new Vector<Integer>();
    elegidos.inicializarVector(n);
    int pos = 0;

    while (i > 0 && j > 0) {
        if (!m.obtenerValor(i, j).equals(m.obtenerValor(i - 1, j))) {
            elegidos.agregarElemento(pos++, i - 1); // Guarda el índice del objeto seleccionado
            j = j - pesos.recuperarElemento(i - 1);
        }
        i--;
    }
    return elegidos;
}

public static int subsecuenciaMasLarga(VectorTDA<Character> s1, VectorTDA<Character> s2) throws Exception {
    int l_s1 = s1.capacidadVector();
    int l_s2 = s2.capacidadVector();

    int dim = Math.max(l_s1 + 1, l_s2 + 1);
    MatrizTDA<Integer> m = new Matriz<Integer>();
    m.inicializarMatriz(dim);

    // Inicializar fila 0 y columna 0 en 0
    for (int i = 0; i <= l_s1; i++) {
        m.setearValor(i, 0, 0);
    }
    for (int j = 0; j <= l_s2; j++) {
        m.setearValor(0, j, 0);
    }

    // Llenado por filas
    for (int i = 1; i <= l_s1; i++) {
        char c1 = s1.recuperarElemento(i - 1);
        for (int j = 1; j <= l_s2; j++) {
            char c2 = s2.recuperarElemento(j - 1);
            if (c1 == c2) {
                m.setearValor(i, j, 1 + m.obtenerValor(i - 1, j - 1));
            } else {
                int arriba = m.obtenerValor(i - 1, j);
                int izquierda = m.obtenerValor(i, j - 1);
                m.setearValor(i, j, Math.max(arriba, izquierda));
            }
        }
    }
    return m.obtenerValor(l_s1, l_s2);
}

// Reconstrucción de la cadena LCS
public static String reconstruirLCS(VectorTDA<Character> s1, VectorTDA<Character> s2, MatrizTDA<Integer> m) {
    int i = s1.capacidadVector();
    int j = s2.capacidadVector();
    StringBuilder sb = new StringBuilder();

    while (i > 0 && j > 0) {
        if (s1.recuperarElemento(i - 1).equals(s2.recuperarElemento(j - 1))) {
            sb.append(s1.recuperarElemento(i - 1));
            i--;
            j--;
        } else if (m.obtenerValor(i - 1, j) >= m.obtenerValor(i, j - 1)) {
            i--;
        } else {
            j--;
        }
    }
    return sb.reverse().toString();
}

public static class ResultadoLIS {
    public int longitud;
    public VectorTDA<Integer> subsecuencia;
    public ResultadoLIS(int l, VectorTDA<Integer> s) {
        this.longitud = l;
        this.subsecuencia = s;
    }
}

public static ResultadoLIS calcularLIS(VectorTDA<Integer> X) {
    int n = X.capacidadVector();
    int[][] D = new int[2][n];

    // Inicialización
    for (int i = 0; i < n; i++) {
        D[0][i] = 1;
        D[1][i] = -1;
    }

    // Llenado cuadrático
    for (int i = 1; i < n; i++) {
        int val_i = X.recuperarElemento(i);
        for (int j = 0; j < i; j++) {
            int val_j = X.recuperarElemento(j);
            if (val_j <= val_i && D[0][j] + 1 >= D[0][i]) {
                D[0][i] = D[0][j] + 1;
                D[1][i] = j;
            }
        }
    }

    // Hallar índice de longitud máxima
    int inx = 0;
    int maxL = D[0][0];
    for (int i = 1; i < n; i++) {
        if (D[0][i] > maxL) {
            maxL = D[0][i];
            inx = i;
        }
    }

    // Reconstrucción hacia atrás de Z
    VectorTDA<Integer> Z = new Vector<Integer>();
    Z.inicializarVector(maxL);
    int curr = inx;
    for (int i = maxL - 1; i >= 0; i--) {
        Z.agregarElemento(i, X.recuperarElemento(curr));
        curr = D[1][curr];
    }

    return new ResultadoLIS(maxL, Z);
}

public static int productoMatrices(VectorTDA<Integer> v) throws Exception {
    int n = v.capacidadVector() - 1;
    MatrizTDA<Integer> m = new Matriz<Integer>();
    m.inicializarMatriz(n);

    // Diagonal principal a 0
    for (int i = 0; i < n; i++) {
        m.setearValor(i, i, 0);
    }

    // Llenado por filas de abajo hacia arriba para respetar dependencias
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i + 1; j < n; j++) {
            int minimo = Integer.MAX_VALUE;
            for (int k = i; k < j; k++) {
                int dim_i = v.recuperarElemento(i);
                int dim_k = v.recuperarElemento(k + 1);
                int dim_j = v.recuperarElemento(j + 1);

                int costo = m.obtenerValor(i, k) + m.obtenerValor(k + 1, j) + (dim_i * dim_k * dim_j);
                if (costo < minimo) {
                    minimo = costo;
                }
            }
            m.setearValor(i, j, minimo);
        }
    }
    return m.obtenerValor(0, n - 1);
}

public static GrafoDirTDA<Integer> floyd(GrafoDirTDA<Integer> grafo) throws Exception {
    // Implementación adaptada a los TDA GrafoDirTDA y ConjuntoTDA de la cátedra UADE
    ConjuntoTDA<Integer> vertices = grafo.Vertices();
    int n = 0;
    ConjuntoTDA<Integer> temp = new Conjunto<Integer>();
    temp.InicializarConjunto();

    // Determinar cantidad de vértices sin destruir el conjunto
    // Se asume vértices numerados de 0 a n-1
    while (!vertices.ConjuntoVacio()) {
        int v = vertices.Elegir();
        temp.Agregar(v);
        vertices.Sacar(v);
        if (v >= n) n = v + 1;
    }

    int INF = 9999999;
    int[][] A = new int[n][n];

    // Inicializar distancias
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                A[i][j] = 0;
            } else if (grafo.ExisteArista(i, j)) {
                A[i][j] = (int) grafo.PesoArista(i, j);
            } else {
                A[i][j] = INF;
            }
        }
    }

    // Bucles k, i, j de Floyd-Warshall
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (A[i][k] != INF && A[k][j] != INF) {
                    if (A[i][k] + A[k][j] < A[i][j]) {
                        A[i][j] = A[i][k] + A[k][j];
                    }
                }
            }
        }
    }

    // Construir grafo dirigido resultado con el cierre métrico
    GrafoDirTDA<Integer> resultado = new GrafoDir<Integer>();
    resultado.InicializarGrafo();
    for (int i = 0; i < n; i++) resultado.AgregarVertice(i);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && A[i][j] != INF) {
                resultado.AgregarArista(i, j, A[i][j]);
            }
        }
    }
    return resultado;
}

public class TSPHeldKarp {
    // Implementación canónica del algoritmo de Held-Karp con Bitmask DP
    public static int resolverTSP(int[][] dist, int n) {
        int INF = 9999999;
        int numEstados = 1 << n; // 2^n estados
        int[][] dp = new int[n][numEstados];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < numEstados; j++) {
                dp[i][j] = INF;
            }
        }

        // Caso base: desde nodo i con conjunto vacío hacia el origen 0
        for (int i = 1; i < n; i++) {
            dp[i][0] = dist[i][0];
        }

        // Iterar por subconjuntos ordenados por cantidad de bits
        for (int mask = 1; mask < (1 << (n - 1)); mask++) {
            int subset = mask << 1; // Desplazado porque el nodo 0 no está en la máscara
            for (int u = 1; u < n; u++) {
                if ((subset & (1 << u)) != 0) continue; // u no debe estar en subset

                int minCosto = INF;
                for (int v = 1; v < n; v++) {
                    if ((subset & (1 << v)) != 0) {
                        int prevSubset = subset ^ (1 << v);
                        int costo = dist[u][v] + dp[v][prevSubset];
                        if (costo < minCosto) minCosto = costo;
                    }
                }
                dp[u][subset] = minCosto;
            }
        }

        // Retorno al origen
        int todoElGrafo = ((1 << n) - 1) ^ 1; // Nodos 1 a n-1
        int res = INF;
        for (int v = 1; v < n; v++) {
            int costo = dist[0][v] + dp[v][todoElGrafo ^ (1 << v)];
            if (costo < res) res = costo;
        }
        return res;
    }
}

