public class ZeroOneKnapsack {
    public static int[][] buildOptimalTable(int[] weights, int[] values, int maxCapacity) {
        int itemCount = weights.length;
        int[][] table = new int[itemCount + 1][maxCapacity + 1];

        for (int itemIndex = 1; itemIndex <= itemCount; itemIndex++) {
            int currentWeight = weights[itemIndex - 1];
            int currentValue = values[itemIndex - 1];
            for (int capacity = 1; capacity <= maxCapacity; capacity++) {
                if (currentWeight > capacity) {
                    table[itemIndex][capacity] = table[itemIndex - 1][capacity];
                } else {
                    int valueWithoutItem = table[itemIndex - 1][capacity];
                    int valueWithItem = currentValue + table[itemIndex - 1][capacity - currentWeight];
                    table[itemIndex][capacity] = Math.max(valueWithoutItem, valueWithItem);
                }
            }
        }
        return table;
    }
}

