def solve_zero_one_knapsack(weights: list[int], values: list[int], max_capacity: int) -> list[list[int]]:
    item_count = len(weights)
    dp_table = [[0] * (max_capacity + 1) for _ in range(item_count + 1)]

    for item_index in range(1, item_count + 1):
        current_weight = weights[item_index - 1]
        current_value = values[item_index - 1]
        for capacity in range(1, max_capacity + 1):
            if current_weight > capacity:
                dp_table[item_index][capacity] = dp_table[item_index - 1][capacity]
            else:
                dp_table[item_index][capacity] = max(
                    dp_table[item_index - 1][capacity],
                    current_value + dp_table[item_index - 1][capacity - current_weight]
                )
    return dp_table

