public class FloydWarshallAllPairs {
    public static void computeAllPairsShortestPaths(int[][] distances, int[][] intermediatePath) {
        int vertexCount = distances.length;
        for (int pivotK = 0; pivotK < vertexCount; pivotK++) {
            for (int sourceI = 0; sourceI < vertexCount; sourceI++) {
                for (int targetJ = 0; targetJ < vertexCount; targetJ++) {
                    if (distances[sourceI][pivotK] != Integer.MAX_VALUE &&
                        distances[pivotK][targetJ] != Integer.MAX_VALUE) {
                        int detourCost = distances[sourceI][pivotK] + distances[pivotK][targetJ];
                        if (detourCost < distances[sourceI][targetJ]) {
                            distances[sourceI][targetJ] = detourCost;
                            intermediatePath[sourceI][targetJ] = pivotK;
                        }
                    }
                }
            }
        }
    }
}

