def floyd_warshall(distance_matrix: list[list[float]]) -> tuple[list[list[float]], list[list[int | None]]]:
    vertex_count = len(distance_matrix)
    distances = [row[:] for row in distance_matrix]
    intermediate: list[list[int | None]] = [[None] * vertex_count for _ in range(vertex_count)]

    for pivot_k in range(vertex_count):
        for source_i in range(vertex_count):
            for target_j in range(vertex_count):
                detour_cost = distances[source_i][pivot_k] + distances[pivot_k][target_j]
                if detour_cost < distances[source_i][target_j]:
                    distances[source_i][target_j] = detour_cost
                    intermediate[source_i][target_j] = pivot_k
    return distances, intermediate

