public class LongestCommonSubsequence {
    public static int computeLength(String firstText, String secondText) {
        int firstLength = firstText.length();
        int secondLength = secondText.length();
        int[][] lcsTable = new int[firstLength + 1][secondLength + 1];

        for (int row = 1; row <= firstLength; row++) {
            for (int col = 1; col <= secondLength; col++) {
                if (firstText.charAt(row - 1) == secondText.charAt(col - 1)) {
                    lcsTable[row][col] = 1 + lcsTable[row - 1][col - 1];
                } else {
                    lcsTable[row][col] = Math.max(lcsTable[row - 1][col], lcsTable[row][col - 1]);
                }
            }
        }
        return lcsTable[firstLength][secondLength];
    }
}

